c='p10';B='PYTHON 6'
S=[]
S.append(TITLE('TIN HỌC · PYTHON 6','TÌM KIẾM VÀ<br>SẮP XẾP','Tìm tuần tự, tìm nhị phân, sắp xếp chọn, nổi bọt, chèn; so sánh và đếm phép so sánh.',['tuần tự','nhị phân','chọn','nổi bọt','chèn']))
S.append(goals(c,B,['Cài đặt <b>tìm kiếm tuần tự</b> và <b>nhị phân</b>.','Mô tả và cài đặt <b>sắp xếp chọn, nổi bọt, chèn</b>.','<b>Trace</b> từng lượt của thuật toán trên dãy cho trước.','Đánh giá <b>độ phức tạp</b>: O(n), O(log n), O(n²).','Dùng <b>sort/sorted</b> và <b>key</b> của Python.'],['Tìm kiếm','Sắp xếp chọn','Sắp xếp nổi bọt, chèn','So sánh các thuật toán','Trọng tâm, HSG']))
S.append(PYR(c,B+' · 1','Tìm kiếm tuần tự','def tim(a, x):\n    for i in range(len(a)):\n        if a[i] == x:\n            return i\n    return -1\n\na = [5, 8, 2, 9, 4]\nprint(tim(a, 9))\nprint(tim(a, 7))',KEY('Duyệt từ đầu, <b>gặp x thì trả về chỉ số</b>; hết dãy không thấy thì trả về <b>-1</b>. Độ phức tạp <b>O(n)</b>; dùng được cho dãy <b>bất kì</b>.'),24))
S.append(S2(c,B+' · 1','Tìm kiếm nhị phân: ý tưởng',card('Điều kiện và ý tưởng',ul(['Dãy phải <b>đã sắp xếp tăng</b>.','So sánh x với phần tử <b>giữa</b> a[m].','Nếu <b>bằng</b>: tìm thấy.','Nếu x <b>lớn hơn</b>: tìm tiếp nửa <b>phải</b>; nhỏ hơn: nửa <b>trái</b>.','Mỗi lần <b>loại một nửa</b> → O(log n).'],6)),RES('<svg viewBox="0 0 520 250" style="width:100%"><g font-family="monospace" font-weight="800" font-size="24" text-anchor="middle"><g fill="#E1BEE7" stroke="#6A1B9A" stroke-width="2"><rect x="10" y="20" width="60" height="50"/><rect x="75" y="20" width="60" height="50"/><rect x="140" y="20" width="60" height="50"/><rect x="205" y="20" width="60" height="50" fill="#FFB300"/><rect x="270" y="20" width="60" height="50"/><rect x="335" y="20" width="60" height="50"/><rect x="400" y="20" width="60" height="50"/></g><g fill="#0B2545"><text x="40" y="53">2</text><text x="105" y="53">5</text><text x="170" y="53">8</text><text x="235" y="53">11</text><text x="300" y="53">15</text><text x="365" y="53">20</text><text x="430" y="53">27</text></g></g><text x="235" y="100" text-anchor="middle" font-size="22" font-weight="800" fill="#C62828">m = 3 → 11</text><text x="260" y="145" text-anchor="middle" font-size="24" font-weight="800" fill="#0B2545">tìm x = 20: 20 &gt; 11</text><text x="260" y="185" text-anchor="middle" font-size="24" font-weight="800" fill="#0B2545">→ bỏ nửa trái, xét nửa phải</text><text x="260" y="225" text-anchor="middle" font-size="22" font-weight="800" fill="#6A1B9A">7 phần tử → 3 → 1: chỉ cần 3 lần</text></svg>','Minh hoạ')))
S.append(PYR(c,B+' · 1','Cài đặt tìm kiếm nhị phân','def nhi_phan(a, x):\n    l, r = 0, len(a) - 1\n    while l <= r:\n        m = (l + r) // 2\n        if a[m] == x:\n            return m\n        if a[m] < x:\n            l = m + 1\n        else:\n            r = m - 1\n    return -1\n\na = [2, 5, 8, 11, 15, 20, 27]\nprint(nhi_phan(a, 20))\nprint(nhi_phan(a, 7))',KEY('Điều kiện lặp <b>l &lt;= r</b>; sau mỗi lần xét <b>l = m + 1</b> hoặc <b>r = m - 1</b> (loại cả a[m]).'),20))
S.append(S2(c,B+' · 1','Trace tìm nhị phân x = 20',CODE('a = [2, 5, 8, 11, 15, 20, 27]\nx = 20  (l=0, r=6)',22),T(tr('Lượt','l','r','m','a[m]','Kết luận',h=True)+tr('1','0','6','3','11','11 &lt; 20: l = 4')+tr('2','4','6','5','20','bằng: trả về 5'))+KEY('Chỉ <b>2 lượt</b> trong khi tìm tuần tự cần 6 lượt. Với n = 10⁹ nhị phân chỉ cần ≈ 30 lượt.')))
S.append(PYR(c,B+' · 1','Nhị phân: tìm vị trí chèn / đếm','import bisect\na = [1, 3, 3, 3, 7, 9]\nprint(bisect.bisect_left(a, 3))\nprint(bisect.bisect_right(a, 3))\nprint(bisect.bisect_right(a, 3) - bisect.bisect_left(a, 3))',KEY('Thư viện <b>bisect</b> có sẵn nhị phân: số lần xuất hiện của 3 = right - left = <b>3</b>.')+WARN('Nhị phân chỉ đúng khi dãy <b>đã sắp xếp</b>.'),22))
S.append(S2(c,B+' · 2','Sắp xếp chọn (selection sort): ý tưởng',card('Ý tưởng',ul(['Lượt i: tìm phần tử <b>nhỏ nhất</b> trong đoạn <b>a[i..n-1]</b>.','<b>Đổi chỗ</b> nó với a[i].','Sau lượt i, a[0..i] đã <b>đúng vị trí</b> cuối cùng.','Lặp <b>n-1</b> lượt.'],6)),KEY('Số phép <b>so sánh</b>: (n-1) + (n-2) + … + 1 = n(n-1)/2 → <b>O(n²)</b>. Số lần <b>đổi chỗ</b> chỉ tối đa n-1.')+OK('Ưu điểm: ít đổi chỗ; nhược: luôn tốn O(n²) so sánh, kể cả dãy đã sắp.')))
S.append(PYR(c,B+' · 2','Cài đặt sắp xếp chọn','def chon(a):\n    n = len(a)\n    for i in range(n - 1):\n        k = i\n        for j in range(i + 1, n):\n            if a[j] < a[k]:\n                k = j\n        a[i], a[k] = a[k], a[i]\n\na = [64, 25, 12, 22, 11]\nchon(a)\nprint(a)',KEY('<b>k</b> lưu vị trí phần tử nhỏ nhất; cuối lượt đổi chỗ <code>a[i], a[k] = a[k], a[i]</code>.'),22))
S.append(S2(c,B+' · 2','Trace sắp xếp chọn',CODE('a = [64, 25, 12, 22, 11]',22),T(tr('Lượt i','Nhỏ nhất ở đoạn','Dãy sau lượt',h=True)+tr('0','11 (vị trí 4)','11 25 12 22 64')+tr('1','12 (vị trí 2)','11 12 25 22 64')+tr('2','22 (vị trí 3)','11 12 22 25 64')+tr('3','25 (vị trí 3)','11 12 22 25 64'))+KEY('Phần <b>đã sắp</b> mở rộng dần từ trái sang phải sau mỗi lượt.')))
S.append(S2(c,B+' · 3','Sắp xếp nổi bọt (bubble sort): ý tưởng',card('Ý tưởng',ul(['So sánh <b>hai phần tử kề nhau</b>; nếu sai thứ tự thì <b>đổi chỗ</b>.','Sau mỗi lượt, phần tử <b>lớn nhất</b> “nổi” về cuối.','Lặp tới khi một lượt <b>không đổi chỗ</b> lần nào.'],6)),KEY('Độ phức tạp <b>O(n²)</b>; với dãy <b>đã sắp</b> và có cờ dừng sớm chỉ <b>O(n)</b>.')+WARN('Nổi bọt đổi chỗ <b>nhiều</b> nhất trong ba thuật toán.')))
S.append(PYR(c,B+' · 3','Cài đặt sắp xếp nổi bọt','def noi_bot(a):\n    n = len(a)\n    for i in range(n - 1):\n        doi = False\n        for j in range(n - 1 - i):\n            if a[j] > a[j + 1]:\n                a[j], a[j + 1] = a[j + 1], a[j]\n                doi = True\n        if not doi:\n            break\n\na = [5, 1, 4, 2, 8]\nnoi_bot(a)\nprint(a)',KEY('Biến cờ <b>doi</b> giúp <b>dừng sớm</b> khi dãy đã sắp. Vòng trong chạy <b>n-1-i</b> lần vì i phần tử cuối đã đúng chỗ.'),20))
S.append(S2(c,B+' · 3','Trace nổi bọt',CODE('a = [5, 1, 4, 2, 8]',22),T(tr('Lượt','Các lần đổi','Dãy cuối lượt',h=True)+tr('1','5↔1, 5↔4, 5↔2','1 4 2 5 8')+tr('2','4↔2','1 2 4 5 8')+tr('3','không đổi','1 2 4 5 8 → dừng'))+KEY('Sau lượt 1, <b>8</b> ở đúng vị trí; sau lượt 2, <b>5</b>… phần tử lớn nối đuôi nhau.')))
S.append(S2(c,B+' · 3','Sắp xếp chèn (insertion sort): ý tưởng',card('Giống xếp bài trên tay',ul(['Giả sử <b>a[0..i-1] đã sắp</b>.','Lấy <b>a[i]</b> làm “lá bài mới”.','<b>Dịch sang phải</b> các phần tử lớn hơn.','<b>Chèn</b> vào vị trí thích hợp.'],6)),KEY('O(n²) nhưng <b>rất nhanh với dãy gần như đã sắp</b> (O(n)). Thực tế hay được dùng cho mảng nhỏ.')))
S.append(PYR(c,B+' · 3','Cài đặt sắp xếp chèn','def chen(a):\n    for i in range(1, len(a)):\n        x = a[i]\n        j = i - 1\n        while j >= 0 and a[j] > x:\n            a[j + 1] = a[j]\n            j -= 1\n        a[j + 1] = x\n\na = [7, 3, 9, 1, 5]\nchen(a)\nprint(a)',KEY('Vòng while <b>dịch</b> các phần tử &gt; x sang phải; <b>a[j+1] = x</b> đặt x vào chỗ trống.')+WARN('Thứ tự điều kiện <code>j &gt;= 0 and a[j] &gt; x</code> quan trọng để không bị IndexError.'),21))
S.append(PYR(c,B+' · 4','Đếm số phép so sánh','def dem(thuat_toan, a):\n    a = a[:]\n    n = len(a)\n    so = 0\n    if thuat_toan == "chon":\n        for i in range(n - 1):\n            k = i\n            for j in range(i + 1, n):\n                so += 1\n                if a[j] < a[k]:\n                    k = j\n            a[i], a[k] = a[k], a[i]\n    return so\n\nfor n in [10, 100, 1000]:\n    print(n, dem("chon", list(range(n, 0, -1))))',KEY('Chọn: đúng <b>n(n-1)/2</b> phép so sánh: 45; 4 950; 499 500 — tăng <b>100 lần</b> khi n tăng 10 lần.'),17))
S.append(TB(c,B+' · 4','So sánh các thuật toán sắp xếp',['Thuật toán','Tốt nhất','Xấu nhất','Đổi chỗ','Ghi chú'],[['Chọn','O(n²)','O(n²)','≤ n-1','ít đổi chỗ'],['Nổi bọt','O(n) (có cờ)','O(n²)','nhiều','đơn giản'],['Chèn','O(n)','O(n²)','dịch nhiều','tốt với dãy gần sắp'],['sort() Python','O(n)','O(n log n)','—','Timsort, ổn định']],mono=1,note=KEY('Cả ba thuật toán cơ bản đều <b>O(n²)</b>; thực tế dùng <b>sort()</b> hoặc <b>sorted()</b>.')))
S.append(PYR(c,B+' · 4','sort, sorted và key','a = ["banh", "an", "chi", "binh"]\nprint(sorted(a))\nprint(sorted(a, key=len))\nprint(sorted(a, key=len, reverse=True))\nds = [("Lan", 8), ("An", 9), ("Binh", 8)]\nprint(sorted(ds, key=lambda t: (-t[1], t[0])))',KEY('<b>key</b> chọn khoá so sánh; <b>reverse=True</b> giảm dần; khoá <b>(-điểm, tên)</b> sắp điểm giảm, đồng điểm theo tên.'),21))
S.append(PYR(c,B+' · 4','Bài toán mẫu: xếp hạng','n = int(input())\nhs = []\nfor _ in range(n):\n    ten, d = input().split()\n    hs.append((float(d), ten))\nhs.sort(reverse=True)\nfor i, (d, ten) in enumerate(hs, 1):\n    print(i, ten, d)',KEY('Lưu cặp <b>(điểm, tên)</b> rồi <b>sort(reverse=True)</b>; <b>enumerate(…, 1)</b> đánh số từ 1.'),21,inp='3\nLan 8.5\nAn 9\nBinh 7\n',lab='Kết quả'))
S+=END(c,B,['<b>Tuần tự</b>: O(n), dãy bất kì. <b>Nhị phân</b>: O(log n), dãy <b>đã sắp</b>.','Nhị phân: <b>l ≤ r</b>, <b>m = (l+r)//2</b>, loại nửa theo so sánh.','<b>Chọn</b>: chọn min rồi đổi chỗ. <b>Nổi bọt</b>: đổi cặp kề. <b>Chèn</b>: chèn vào đoạn đã sắp.','Cả ba đều <b>O(n²)</b>; thực tế dùng <b>sort()</b> O(n log n).','<b>Trace</b> từng lượt là kĩ năng chính của đề thi.'],[('Dãy đã sắp, n lớn','nhị phân'),('Ít đổi chỗ','sắp chọn'),('Gần như đã sắp','sắp chèn'),('Giảm dần','sort(reverse=True)')],'Nhị phân yêu cầu dãy <b>đã sắp</b>; quên cập nhật l, r gây lặp vô hạn.',['<code>m = (l + r) // 2</code> luôn đúng với số nguyên Python (không tràn số).','Sắp chọn <b>không ổn định</b>: có thể đảo thứ tự hai phần tử bằng nhau.','Nổi bọt và chèn <b>ổn định</b>.','Tìm nhị phân dùng <code>bisect</code>.'],['<b>Sắp xếp trộn (merge sort)</b> và <b>nhanh (quick sort)</b>: O(n log n) (chia để trị, Python 7).','<b>Sắp xếp đếm</b> O(n + k) khi giá trị nhỏ.','Tìm nhị phân trên <b>đáp số</b> (bài toán “tìm kết quả nhỏ nhất thoả điều kiện”).'],
 [('Cần tối đa bao nhiêu lần so sánh để tìm một số trong dãy 1000 phần tử đã sắp bằng nhị phân?',),('Sắp xếp tăng dần <code>[4, 3, 2, 1]</code> bằng nổi bọt: sau lượt 1 dãy là gì?',),('Sắp xếp chọn dãy <code>[3, 1, 2]</code>: sau lượt 1?',),('Có thể dùng nhị phân trên dãy chưa sắp không? Vì sao?',),('Viết hàm đếm số lần xuất hiện của x trong dãy đã sắp bằng bisect.',)],
 [('⌈log₂ 1000⌉ ≈ <b>10</b> lần (2¹⁰ = 1024).',),(RUN('a=[4,3,2,1]\nfor j in range(3):\n    if a[j]>a[j+1]: a[j],a[j+1]=a[j+1],a[j]\nprint(a)')+' (số 4 nổi về cuối)',),(RUN('a=[3,1,2]\nk=0\nfor j in range(1,3):\n    if a[j]<a[k]: k=j\na[0],a[k]=a[k],a[0]\nprint(a)'),),('Không: nhị phân dựa vào thứ tự để loại nửa; dãy chưa sắp cho kết quả sai.',),('<code>from bisect import *\\ndef dem(a,x): return bisect_right(a,x)-bisect_left(a,x)</code>',)],
 [('Dự đoán kết quả và đếm số lần đổi chỗ của nổi bọt:',"a = [3, 2, 1]\nd = 0\nfor i in range(2):\n    for j in range(2 - i):\n        if a[j] > a[j + 1]:\n            a[j], a[j + 1] = a[j + 1], a[j]\n            d += 1\nprint(a, d)"),
  ('Nhị phân: dãy <code>[1,3,5,7,9,11,13]</code>, tìm 11. Liệt kê các giá trị m trong từng lượt.',),
  ('Sắp chèn dãy <code>[5, 2, 4, 6, 1, 3]</code>: viết dãy sau mỗi lần chèn (i = 1..5).',),
  ('Cho dãy n số. Viết chương trình in ra phần tử xuất hiện nhiều nhất (nếu hoà, lấy nhỏ nhất) bằng cách sắp xếp.',),
  ('Một dãy đã sắp tăng bị xoay (ví dụ <code>[6,7,8,1,2,3]</code>). Nêu cách tìm số nhỏ nhất bằng ý tưởng nhị phân.',),
  ('Vì sao sắp chèn nhanh với dãy gần sắp xếp, còn sắp chọn thì không?',)],
 [(RUN("a = [3, 2, 1]\nd = 0\nfor i in range(2):\n    for j in range(2 - i):\n        if a[j] > a[j + 1]:\n            a[j], a[j + 1] = a[j + 1], a[j]\n            d += 1\nprint(a, d)")+' (đảo ngược hoàn toàn: n(n-1)/2 = 3 lần đổi)',),
  ('l=0,r=6: m=3 (7 &lt; 11 → l=4); m=5 (11 = 11 → tìm thấy). Các m: <b>3, 5</b>.',),
  ('i=1: 2 5 4 6 1 3; i=2: 2 4 5 6 1 3; i=3: 2 4 5 6 1 3; i=4: 1 2 4 5 6 3; i=5: 1 2 3 4 5 6.',),
  ('<code>a.sort(); duyệt đếm dãy liên tiếp bằng nhau, giữ max (dấu &gt; để hoà lấy nhỏ nhất)</code>. Sắp xếp xong, các giá trị bằng nhau đứng cạnh nhau.',),
  ('So sánh a[m] với a[r]: nếu a[m] &gt; a[r] thì min nằm bên phải m (l = m+1); ngược lại r = m. Lặp đến l = r: O(log n).',),
  ('Sắp chèn chỉ dịch ít phần tử nếu dãy gần sắp (≈ n bước). Sắp chọn luôn quét hết phần còn lại để tìm min: luôn ≈ n²/2 so sánh.',)],hper=2)
